import ast,base64,json,copy
d=json.loads(base64.b64decode(""));a,b=ast.parse(d["before"]),ast.parse(d["after"]);c=[]
def ck(n,v):
 if not v:raise AssertionError(n)
 c.append(n)
defs=lambda m:{n.name:n for n in m.body if isinstance(n,(ast.FunctionDef,ast.ClassDef))}
ad,bd=defs(a),defs(b)
ck("same_five_definition_names",set(ad)==set(bd) and len(ad)==5)
for n in ad:ck(n+"_whole_definition_byte_identical",ast.get_source_segment(d["before"],ad[n])==ast.get_source_segment(d["after"],bd[n]))
assign=lambda m:{n.targets[0].id:n for n in m.body if isinstance(n,ast.Assign) and len(n.targets)==1 and isinstance(n.targets[0],ast.Name)}
aa,bb=assign(a),assign(b)
ck("exact_three_ready_source_pins",ast.literal_eval(bb["PINS"].value)==d["pins"])
ck("same_top_level_assignment_names",set(aa)==set(bb))
# Only BASE path namespace, PINS, and three schema string occurrences may change.
expected_base="normal-same-root-publication-x230-transfer-controls-r1"
ck("BASE_exact_fixed_namespace",isinstance(bb["BASE"].value,ast.BinOp) and isinstance(bb["BASE"].value.right,ast.Constant) and bb["BASE"].value.right.value==expected_base)
normalized=copy.deepcopy(b)
for n in normalized.body:
 if isinstance(n,ast.Assign) and len(n.targets)==1 and isinstance(n.targets[0],ast.Name) and n.targets[0].id in ["BASE","PINS"]:n.value=copy.deepcopy(aa[n.targets[0].id].value)
av=[x for x in ast.walk(a) if isinstance(x,ast.Constant)]
bv=[x for x in ast.walk(normalized) if isinstance(x,ast.Constant)]
ck("same_AST_constant_count_after_pin_base_reversal",len(av)==len(bv))
changes=[]
for old,new in zip(av,bv,strict=True):
 if old.value!=new.value:
  ck("schema_literal_change_only",isinstance(old.value,str) and isinstance(new.value,str) and old.value.startswith("heptabao.") and new.value.startswith("heptabao.") and "x230" in old.value and "x230" in new.value)
  changes.append({"before":old.value,"after":new.value})
  new.value=old.value
ck("two_inert_input_schema_literals",len(changes)==2)
ck("whole_AST_exact_after_declared_literals",ast.dump(normalized,include_attributes=False)==ast.dump(a,include_attributes=False))
print(json.dumps({"schema":"heptabao.root-X230-inert-publisher-AST.r30.v1","status":"PASS_SOURCE_ONLY","checks_passed":len(c),"checks":c,"whole_unchanged_definitions":5,"schema_literal_changes":changes,"source_executed":False,"Runtime_calls":0},sort_keys=True))
